 let input: unknown;
 try { input = await read(); } catch { return {kind:"unavailable"}; }
 if (!Array.isArray(input)) return {kind:"invalid-batch"};
 const seen = new Set<string>();
 let open=0, done=0, rejected=0, duplicates=0;
 for (const row of input) {
